# Writes the generated test files in this folder and manifest.json, which
# records the expected result of each one.
#
#   elixir mock_data/generate.exs              # rewrite every generated file
#   elixir mock_data/generate.exs --large 15000 # also write the Z7 large-batch zip (not committed)
#
# The cases are defined in generators/json_claims.exs and
# generators/x12_files.exs: edit those, never the files or manifest.json.
# Files listed in the previous manifest are deleted first, so a renamed or
# removed case leaves nothing behind. Hand-written files (not in the
# manifest) are never touched.
#
# Check the results with
#   cd phoenix_web && mix run --no-start ../mock_data/verify.exs

root = Path.dirname(__ENV__.file)
manifest_path = Path.join(root, "manifest.json")
{opts, _} = OptionParser.parse!(System.argv(), strict: [large: :integer])

pretty_json = fn term ->
  (term |> JSON.encode!() |> :json.decode() |> :json.format() |> IO.iodata_to_binary()) <> "\n"
end

write = fn rel, content ->
  path = Path.join(root, rel)
  File.mkdir_p!(Path.dirname(path))
  File.write!(path, content)
end

write_zip = fn rel, entries ->
  path = Path.join(root, rel)
  File.mkdir_p!(Path.dirname(path))
  File.rm(path)
  zip_entries = Enum.map(entries, fn {name, data} -> {String.to_charlist(name), data} end)
  {:ok, _} = :zip.create(String.to_charlist(path), zip_entries)
end

{x12_cases, _} = Code.eval_file(Path.join(root, "generators/x12_files.exs"))

case opts[:large] do
  nil ->
    {json_cases, _} = Code.eval_file(Path.join(root, "generators/json_claims.exs"))

    if File.exists?(manifest_path) do
      for %{"file" => rel} <- manifest_path |> File.read!() |> JSON.decode!() |> Map.fetch!("cases") do
        path = Path.join(root, rel)
        File.rm(path)
        # Remove folders the deletion left empty, up to (not including) root.
        path |> Path.dirname() |> Stream.iterate(&Path.dirname/1) |> Enum.take_while(&(&1 != root)) |> Enum.each(&File.rmdir/1)
      end
    end

    # One shape for both: string keys, no nil fields.
    cases =
      (x12_cases ++ json_cases)
      |> Enum.map(fn c ->
        case c[:zip_entries] do
          nil -> write.(c[:file] || c["file"], c[:content] || c["content"])
          entries -> write_zip.(c[:file], entries)
        end

        c
        |> Map.drop([:content, "content", :zip_entries])
        |> JSON.encode!()
        |> JSON.decode!()
        |> Map.reject(fn {_, v} -> is_nil(v) end)
      end)
      |> Enum.sort_by(& &1["file"])

    manifest = %{
      "about" =>
        "Expected results for each generated file, checked by mock_data/verify.exs. " <>
          "`matched` is the exact set of rules that should match: the active business rules seeded by " <>
          "priv/repo/seeds.exs, or the rules file named in `rules`. `not_checked` is the exact set of rules " <>
          "reported as not checked. `nppes` is ok or text the NPPES rejection must contain. `known_issue` marks " <>
          "a case the current code gets wrong. Generated by generate.exs; edit the generators, not this file.",
      "cases" => cases
    }

    File.write!(manifest_path, pretty_json.(manifest))
    IO.puts("#{length(cases)} files and manifest.json written under #{root}")

  n ->
    {meta, entries} = apply(X12Suite.Cases, :large, [n])
    write_zip.(meta.file, entries)
    write.(String.replace_suffix(meta.file, ".zip", ".json"), pretty_json.(meta))
    IO.puts("Wrote #{meta.file} (#{n} claims); not committed, see .gitignore")
end
